classDiagram
    class ApprovedInvocationEnvelopeV1 {
        +invocationId
        +decisionId
        +bindingHash
        +scope
        +deadline
        +leaseHandles
    }
    class CapabilityDescriptorV1 {
        +capabilityId
        +versionHash
        +sideEffectClass
        +idempotency
        +featureSet
        +platformSet
    }
    class ApprovedInvocationGateway {
        +admit(ApprovedInvocationEnvelopeV1)
        +cancel(HostControlEnvelopeV1)
        +emit(HostInvocationEventV1)
    }
    class AdapterCapabilityRegistry {
        +resolveExactBinding()
        +materializeAttestedSet()
    }
    class ModelProviderGateway {
        +execute(ModelRequestV1)
        +resolveFrozenCandidate()
    }
    class ProviderEnginePortV1 {
        +start(ModelRequestV1)
        +cancel()
    }
    class RigTranslationAdapterV1 {
        +toRig()
        +fromRig()
    }
    class BuiltInToolRuntime {
        +execute(ToolInvocationV1)
        +enforceAuthorityMode()
    }
    class McpSessionManager {
        +initialize()
        +call(McpCallV1)
    }
    class TrustedPluginRuntime {
        +inspectManifestInert()
        +invoke(PluginInvocationV1)
    }
    class ExternalAgentManager {
        +negotiate()
        +start()
        +continueNativeSession()
        +cancel()
    }
    class IsolationBackendPortV1 {
        +verifyEnforcement()
        +executeIsolated()
    }
    class SecretLeaseMaterializer {
        +redeem()
        +redactionSet()
        +zeroize()
    }
    class ResultOutcomeNormalizer {
        +normalize()
        +classifyEffectOutcome()
    }
    class ProcessRuntime {
        +spawnNormalized()
        +cancelTree()
        +reportHealth()
    }
    ApprovedInvocationGateway --> AdapterCapabilityRegistry : exact binding only
    ApprovedInvocationGateway --> ModelProviderGateway : approved model
    ApprovedInvocationGateway --> BuiltInToolRuntime : approved tool
    ApprovedInvocationGateway --> McpSessionManager : approved MCP
    ApprovedInvocationGateway --> TrustedPluginRuntime : approved plugin
    ApprovedInvocationGateway --> ExternalAgentManager : explicit agent
    ModelProviderGateway ..> ProviderEnginePortV1 : stable Aworkit port
    ProviderEnginePortV1 <|.. RigTranslationAdapterV1 : replaceable adapter
    BuiltInToolRuntime --> IsolationBackendPortV1 : sandboxed mode
    TrustedPluginRuntime --> IsolationBackendPortV1 : optional explicit isolation
    ExternalAgentManager --> McpSessionManager : negotiated forwarding
    ModelProviderGateway --> SecretLeaseMaterializer : minimal slots
    BuiltInToolRuntime --> SecretLeaseMaterializer : minimal slots
    McpSessionManager --> SecretLeaseMaterializer : minimal slots
    TrustedPluginRuntime --> SecretLeaseMaterializer : explicit lease only
    ExternalAgentManager --> SecretLeaseMaterializer : explicit lease only
    ApprovedInvocationGateway --> ProcessRuntime : lifecycle facts
    ResultOutcomeNormalizer --> ApprovedInvocationGateway : normalized events
    ProcessRuntime --> ResultOutcomeNormalizer : exact milestones
    SecretLeaseMaterializer --> ResultOutcomeNormalizer : redaction only
